.cell {
  --cell-bg: transparent;
  position: relative;
  isolation: isolate;
  display: flex;
  align-items: center;
  justify-content: center;
  min-width: 0;
  font-variant-numeric: tabular-nums;
  line-height: 1;
  color: var(--awake-ink);
  cursor: default;
  user-select: none;
}

/* The pill behind the label. Adjacent cells with the same state fuse into one run. */
.cell::before {
  content: "";
  position: absolute;
  z-index: -1;
  background: var(--cell-bg);
  transition: background-color 0.2s, inset 0.2s;
}

/* Column / row crosshair while hovering. */
.cell::after {
  content: "";
  position: absolute;
  z-index: 1;
  pointer-events: none;
  opacity: 0;
  transition: opacity 0.12s;
}

.highlighted::after {
  opacity: 1;
}

.time {
  font-weight: 550;
  letter-spacing: -0.01em;
}

.minutes {
  font-size: 0.72em;
  font-weight: 600;
  opacity: 0.8;
}

.period {
  font-size: 10px;
  font-weight: 500;
  opacity: 0.62;
}

/* ---- States ------------------------------------------------------------ */

.asleep {
  --cell-bg: repeating-linear-gradient(135deg, transparent 0 4px, var(--asleep-stripe) 4px 5px);
  color: var(--asleep-ink);
}

.awake {
  --cell-bg: var(--awake-bg);
}

.overlap {
  --cell-bg: var(--overlap-bg);
  color: var(--overlap-ink);
}

.overlap .time {
  font-weight: 750;
}

.overlap .period {
  opacity: 0.85;
  font-weight: 650;
}

/* ---- Day boundary ------------------------------------------------------ */

.dayStart[data-day] .time::before {
  content: attr(data-day);
}

.dayStart::after {
  opacity: 1;
}

/* ---- Horizontal (desktop rows) ---------------------------------------- */

.horizontal {
  flex-direction: column;
  gap: 3px;
  height: 52px;
}

.horizontal .time {
  font-size: clamp(11.5px, 1.05vw, 14px);
}

.horizontal::before {
  inset: 5px 0;
}

.horizontal.runStart::before {
  left: 2px;
  border-top-left-radius: 9px;
  border-bottom-left-radius: 9px;
}

.horizontal.runEnd::before {
  right: 2px;
  border-top-right-radius: 9px;
  border-bottom-right-radius: 9px;
}

